"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useMemo, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** How often the plan bills. */
export type BillingPeriod = "monthly" | "yearly";

/** Props for a billing toggle. Pass `value` to control it, or `defaultValue` to let it hold its own choice. */
export type BillingToggleProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onChange" | "defaultValue"> & {
  /** The price of one month when the plan bills every month. */
  monthlyPrice: number;
  /** The price of one whole year when the plan bills once a year. */
  yearlyPrice: number;
  value?: BillingPeriod;
  defaultValue?: BillingPeriod;
  onValueChange?: (value: BillingPeriod) => void;
  /** An ISO 4217 code such as "EUR". It defaults to "USD". */
  currency?: string;
  /** A BCP 47 locale such as "en-GB". It defaults to "en-US", so the server and the browser render the same text. */
  locale?: string;
  /** Names the radio group for screen readers. It defaults to "Billing period". */
  "aria-label"?: string;
};

// Critically damped: the thumb confirms a choice, so it arrives without a wobble.
const SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
// The system announces a new price, so the digits ease out and land once.
const ROLL: Transition = { duration: 0.45, ease: [0.165, 0.84, 0.44, 1] };
const REVEAL: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const FADE: Transition = { duration: 0.15 };
const INSTANT: Transition = { duration: 0 };

const PERIODS = [
  { value: "monthly", label: "Monthly", unit: "per month" },
  { value: "yearly", label: "Yearly", unit: "per year" },
] as const satisfies readonly { value: BillingPeriod; label: string; unit: string }[];

const KEY_TARGET = {
  ArrowLeft: "monthly",
  ArrowUp: "monthly",
  Home: "monthly",
  ArrowRight: "yearly",
  ArrowDown: "yearly",
  End: "yearly",
} as const satisfies { [key: string]: BillingPeriod };

const isMoveKey = (key: string): key is keyof typeof KEY_TARGET => key in KEY_TARGET;

function DigitColumn({ digit, digits, transition }: { digit: number; digits: string[]; transition: Transition }) {
  return (
    <span className="relative inline-block overflow-hidden">
      {/* The invisible zero sizes the window, so the column needs no measured height. */}
      <span className="invisible">{digits[0]}</span>
      <motion.span
        initial={false}
        animate={{ y: `${-digit * 10}%` }}
        transition={transition}
        className="absolute inset-x-0 top-0 flex flex-col items-center"
      >
        {digits.map((glyph) => (
          <span key={glyph}>{glyph}</span>
        ))}
      </motion.span>
    </span>
  );
}

/**
 * Chooses monthly or yearly billing for one plan and shows what that choice
 * costs. The thumb slides to the choice, the price digits roll to the new
 * amount, and a badge shows the saving while yearly is chosen.
 */
export function BillingToggle({
  monthlyPrice,
  yearlyPrice,
  value,
  defaultValue = "monthly",
  onValueChange,
  currency = "USD",
  locale = "en-US",
  "aria-label": ariaLabel = "Billing period",
  className,
  ...rootProps
}: BillingToggleProps) {
  const [ownValue, setOwnValue] = useState<BillingPeriod>(defaultValue);
  const period = value ?? ownValue;
  const yearly = period === "yearly";
  const reduceMotion = useReducedMotion() ?? false;
  const radios = useRef(new Map<BillingPeriod, HTMLButtonElement>());

  // Cents show only when a price has them, and then on both prices, so the
  // digit columns keep their places when the period changes.
  const cents = Number.isInteger(monthlyPrice) && Number.isInteger(yearlyPrice) ? 0 : 2;
  const formatter = useMemo(
    () => new Intl.NumberFormat(locale, { style: "currency", currency, minimumFractionDigits: cents, maximumFractionDigits: cents }),
    [cents, currency, locale],
  );
  // A locale may write digits in another script. The columns roll through that script's ten digits.
  const digits = useMemo(() => {
    const plain = new Intl.NumberFormat(locale, { numberingSystem: formatter.resolvedOptions().numberingSystem, useGrouping: false });
    return Array.from({ length: 10 }, (_, digit) => plain.format(digit));
  }, [formatter, locale]);

  const price = formatter.format(yearly ? yearlyPrice : monthlyPrice);
  const unit = PERIODS[yearly ? 1 : 0].unit;
  const fullYear = monthlyPrice * 12;
  const saving = fullYear > yearlyPrice ? Math.round((1 - yearlyPrice / fullYear) * 100) : 0;
  const badge = yearly && saving > 0 ? `Save ${saving}%` : null;
  // Each glyph is keyed by its place from the right, so a digit that changes keeps its column and rolls.
  const glyphs = [...price].map((char, index, all) => ({ char, place: all.length - 1 - index }));

  const select = (next: BillingPeriod) => {
    if (next === period) return;
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!isMoveKey(event.key)) return;
    const next = KEY_TARGET[event.key];
    event.preventDefault();
    radios.current.get(next)?.focus();
    select(next);
  };

  return (
    <div {...rootProps} data-period={period} className={cn("inline-flex flex-col items-start gap-4", className)}>
      <div
        role="radiogroup"
        aria-label={ariaLabel}
        onKeyDown={handleKeyDown}
        className="relative grid grid-cols-2 rounded-full bg-muted p-1"
      >
        {/* Half the track wide, so moving it by its own width lands on the second option. */}
        <span aria-hidden="true" className="pointer-events-none absolute inset-1 flex">
          <motion.span
            initial={false}
            animate={{ x: yearly ? "100%" : "0%" }}
            transition={reduceMotion ? INSTANT : SPRING}
            className="w-1/2 rounded-full bg-background shadow-sm"
          />
        </span>
        {PERIODS.map((option) => {
          const checked = option.value === period;
          return (
            <button
              key={option.value}
              ref={(node) => {
                if (node) radios.current.set(option.value, node);
                else radios.current.delete(option.value);
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={checked ? 0 : -1}
              onClick={() => select(option.value)}
              className={cn(
                "group relative min-h-11 cursor-pointer touch-manipulation rounded-full px-5 text-sm font-medium outline-none motion-safe:transition-colors motion-safe:duration-200",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-muted",
                checked ? "text-foreground" : "text-muted-foreground hover:text-foreground",
              )}
            >
              <span className="inline-block group-active:scale-95 motion-safe:transition-transform motion-safe:duration-150">
                {option.label}
              </span>
            </button>
          );
        })}
      </div>
      <p aria-live="polite" className="flex min-h-10 items-center gap-2 text-foreground">
        <span className="sr-only">{[`${price} ${unit}`, badge].filter(Boolean).join(". ")}</span>
        <span aria-hidden="true" className="inline-flex text-4xl font-semibold tabular-nums">
          {glyphs.map(({ char, place }) =>
            digits.includes(char) ? (
              <DigitColumn
                key={place}
                digit={digits.indexOf(char)}
                digits={digits}
                transition={reduceMotion ? INSTANT : ROLL}
              />
            ) : (
              <span key={place} className="whitespace-pre">
                {char}
              </span>
            ),
          )}
        </span>
        <span aria-hidden="true" className="self-end pb-1 text-sm text-muted-foreground">
          {unit}
        </span>
        <AnimatePresence initial={false}>
          {badge ? (
            <motion.span
              key="badge"
              aria-hidden="true"
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.9, x: -8 }}
              animate={{ opacity: 1, scale: 1, x: 0 }}
              exit={{ opacity: 0, transition: FADE }}
              transition={reduceMotion ? FADE : REVEAL}
              className="rounded-full bg-primary px-2.5 py-1 text-xs font-medium text-primary-foreground"
            >
              {badge}
            </motion.span>
          ) : null}
        </AnimatePresence>
      </p>
    </div>
  );
}
